import java.util.ArrayList;
import java.util.List;

public class ArrayListBasico {
    public static void main(String[] args) {
        // Crear una lista vacía de Strings
        List<String> nombres = new ArrayList<>();

        // add() — añade al final
        nombres.add("Ana");
        nombres.add("Carlos");
        nombres.add("Maria");
        nombres.add("Pedro");
        System.out.println("Lista: " + nombres);
        System.out.println("Tamano: " + nombres.size());

        // add(indice, elemento) — inserta en una posicion
        nombres.add(1, "Laura"); // Inserta antes de Carlos
        System.out.println("Despues de insertar Laura: " + nombres);

        // get(indice) — obtiene un elemento
        System.out.println("Primero: " + nombres.get(0));
        System.out.println("Tercero: " + nombres.get(2));

        // set(indice, elemento) — reemplaza un elemento
        nombres.set(2, "Laura2");
        System.out.println("Despues de set: " + nombres);

        // remove(indice) — elimina por posicion
        String eliminado = nombres.remove(3);
        System.out.println("Eliminado: " + eliminado);
        System.out.println("Lista final: " + nombres);

        // contains() — busca un elemento
        System.out.println("Contiene Ana: " + nombres.contains("Ana"));
        System.out.println("Contiene Pedro: " + nombres.contains("Pedro"));

        // indexOf() — posicion de un elemento
        System.out.println("Indice de Maria: " + nombres.indexOf("Maria"));
    }
}

