public class IteratorBasico {
    public static void main(String[] args) {
        List<String> frutas = new ArrayList<>();
        frutas.add("Manzana");
        frutas.add("Platano");
        frutas.add("Naranja");
        frutas.add("Pera");
        frutas.add("Uva");

        // Obtener el iterador
        Iterator<String> it = frutas.iterator();

        // Recorrer con hasNext() y next()
        while (it.hasNext()) {
            String fruta = it.next();
            System.out.println("Fruta: " + fruta);
        }

        System.out.println();

        // Eliminar elementos durante el recorrido
        Iterator<String> it2 = frutas.iterator();
        while (it2.hasNext()) {
            String fruta = it2.next();
            if (fruta.startsWith("P")) {
                it2.remove(); // Elimina de forma segura
            }
        }
        System.out.println("Sin frutas que empiezan por P: " + frutas);
    }
}

