import java.util.ArrayList;
import java.util.List;
import java.util.ListIterator;

public class ListIteratorEjemplo {
    public static void main(String[] args) {
        List<String> colores = new ArrayList<>();
        colores.add("Rojo");
        colores.add("Verde");
        colores.add("Azul");

        // ListIterator permite ir hacia adelante y hacia atras
        ListIterator<String> it = colores.listIterator();

        // Hacia adelante
        System.out.println("Hacia adelante:");
        while (it.hasNext()) {
            System.out.println(it.next());
        }

        // Hacia atras (el puntero esta al final)
        System.out.println("Hacia atras:");
        while (it.hasPrevious()) {
            System.out.println(it.previous());
        }

        // Modificar un elemento durante el recorrido
        ListIterator<String> it2 = colores.listIterator();
        while (it2.hasNext()) {
            String color = it2.next();
            if (color.equals("Verde")) {
                it2.set("Morado"); // Reemplaza el ultimo next()
            }
        }
        System.out.println("Despues de modificar: " + colores);
    }
}

