import java.util.List;

public class Maximo {
    public static <T extends Comparable<T>> T maximo(List<T> lista) {
        T max = lista.get(0);
        for (int i = 1; i < lista.size(); i++) {
            if (lista.get(i).compareTo(max) > 0) {
                max = lista.get(i);
            }
        }
        return max;
    }

    public static void main(String[] args) {
        List<Integer> numeros = List.of(3, 7, 1, 9, 4);
        System.out.println("Maximo: " + maximo(numeros)); // 9

        List<String> nombres = List.of("Ana", "Pedro", "Carlos");
        System.out.println("Maximo: " + maximo(nombres)); // Pedro
    }
}

public class ListaGenerica<T> {
    private Object[] elementos;
    private int tamano;
    private static final int CAPACIDAD_INICIAL = 10;

    public ListaGenerica() {
        this.elementos = new Object[CAPACIDAD_INICIAL];
        this.tamano = 0;
    }

    public void add(T elemento) {
        if (tamano == elementos.length) {
            Object[] nuevo = new Object[elementos.length * 2];
            System.arraycopy(elementos, 0, nuevo, 0, tamano);
            elementos = nuevo;
        }
        elementos[tamano++] = elemento;
    }

    @SuppressWarnings("unchecked")
    public T get(int indice) {
        if (indice < 0 || indice >= tamano) throw new IndexOutOfBoundsException();
        return (T) elementos[indice];
    }

    public int size() { return tamano; }

    public static void main(String[] args) {
        ListaGenerica<String> lista = new ListaGenerica<>();
        lista.add("Ana");
        lista.add("Carlos");
        System.out.println(lista.get(0)); // Ana
        System.out.println(lista.size()); // 2
    }
}

