import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.ArrayList;
import java.util.List;

public class AnalizadorLogs {
    record LogEntry(String fecha, String accion, String alumno, String curso, double nota) {}

    private static final Pattern PATRON = Pattern.compile(
        "\\[(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2})\\] (\\w+) alumno:(\\w+) curso:(\\w+) nota:(\\d+\\.?\\d*)"
    );

    public static List<LogEntry> analizar(String[] lineas) {
        List<LogEntry> entradas = new ArrayList<>();
        for (String linea : lineas) {
            Matcher m = PATRON.matcher(linea);
            if (m.matches()) {
                entradas.add(new LogEntry(
                    m.group(1), m.group(2), m.group(3),
                    m.group(4), Double.parseDouble(m.group(5))
                ));
            }
        }
        return entradas;
    }

    public static void main(String[] args) {
        String[] logs = {
            "[2026-09-15 10:30:45] MATRICULA alumno:Ana curso:Prog nota:8.5",
            "[2026-09-15 10:31:00] MATRICULA alumno:Carlos curso:Prog nota:7.0"
        };
        for (LogEntry e : analizar(logs)) {
            System.out.println(e);
        }
    }
}

