import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import java.io.File;

public class LeerXML {
    public static void main(String[] args) throws Exception {
        // Crear un archivo XML de ejemplo
        String xml = """
            <?xml version="1.0" encoding="UTF-8"?>
            <alumnos>
                <alumno>
                    <nombre>Ana</nombre>
                    <email>ana@email.com</email>
                    <nota>8.5</nota>
                </alumno>
                <alumno>
                    <nombre>Carlos</nombre>
                    <email>carlos@email.com</email>
                    <nota>7.0</nota>
                </alumno>
            </alumnos>
            """;

        // Escribir el XML a un archivo temporal
        java.nio.file.Files.writeString(
            java.nio.file.Path.of("alumnos.xml"), xml);

        // Leer el XML
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document doc = builder.parse(new File("alumnos.xml"));

        // Obtener todos los nodos "alumno"
        NodeList alumnos = doc.getElementsByTagName("alumno");

        for (int i = 0; i < alumnos.getLength(); i++) {
            Element alumno = (Element) alumnos.item(i);
            String nombre = alumno.getElementsByTagName("nombre")
                .item(0).getTextContent();
            String email = alumno.getElementsByTagName("email")
                .item(0).getTextContent();
            String nota = alumno.getElementsByTagName("nota")
                .item(0).getTextContent();
            System.out.printf("%s (%s) - Nota: %s%n", nombre, email, nota);
        }
    }
}

