public class PersistenciaJSON {
    private static final String ARCHIVO = "alumnos.json";
    private static final Gson gson = new GsonBuilder().setPrettyFormatting().create();

    public static void guardar(List<Alumno> alumnos) throws IOException {
        try (Writer writer = new FileWriter(ARCHIVO)) {
            gson.toJson(alumnos, writer);
        }
    }

    public static List<Alumno> cargar() throws IOException {
        try (Reader reader = new FileReader(ARCHIVO)) {
            Type tipoLista = new TypeToken<List<Alumno>>(){}.getType();
            return gson.fromJson(reader, tipoLista);
        }
    }

