        List<Alumno> alumnos = new ArrayList<>();
        alumnos.add(new Alumno("Ana", "ana@email.com"));
        alumnos.add(new Alumno("Carlos", "carlos@email.com"));

        guardar(alumnos);
        System.out.println("Guardados " + alumnos.size() + " alumnos");

        List<Alumno> cargados = cargar();
        System.out.println("Cargados " + cargados.size() + " alumnos");
        for (Alumno a : cargados) {
            System.out.println(a.getNombre());
        }
    }
}

