import java.util.List;

public class ReduceEjemplo {
    public static void main(String[] args) {
        List<Alumno> alumnos = List.of(
            new Alumno("Ana", "ana@email.com"),
            new Alumno("Carlos", "carlos@email.com"),
            new Alumno("Maria", "maria@email.com")
        );

        // === REDUCE BASICO: sumar notas ===
        double suma = alumnos.stream()
            .mapToDouble(Alumno::getNotaMedia)
            .reduce(0.0, Double::sum);
        System.out.println("Suma total: " + suma);

        // === MEDIA: suma / count ===
        double media = alumnos.stream()
            .mapToDouble(Alumno::getNotaMedia)
            .average()
            .orElse(0.0);
        System.out.println("Media: " + media);

        // === MAXIMO y MINIMO ===
        double maxima = alumnos.stream()
            .mapToDouble(Alumno::getNotaMedia)
            .max()
            .orElse(0.0);
        System.out.println("Maxima: " + maxima);

        double minima = alumnos.stream()
            .mapToDouble(Alumno::getNotaMedia)
            .min()
            .orElse(0.0);
        System.out.println("Minima: " + minima);

        // === CONTAR: cuantos aprobados ===
        long numAprobados = alumnos.stream()
            .filter(a -> a.getNotaMedia() >= 5.0)
            .count();
        System.out.println("Aprobados: " + numAprobados);
    }
}

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class PipelineCompleto {
    public static void main(String[] args) {
        List<Alumno> alumnos = List.of(
            new Alumno("Ana", "ana@email.com"),
            new Alumno("Carlos", "carlos@email.com"),
            new Alumno("Maria", "maria@email.com"),
            new Alumno("Pedro", "pedro@email.com"),
            new Alumno("Laura", "laura@email.com")
        );
        // Suponiendo que cada alumno tiene notas asignadas

        // Pipeline 1: Nombres de aprobados, ordenados
        System.out.println("=== Aprobados ordenados ===");
        List<String> aprobadosOrdenados = alumnos.stream()
            .filter(a -> a.getNotaMedia() >= 5.0)
            .map(Alumno::getNombre)
            .sorted()
            .toList();
        aprobadosOrdenados.forEach(System.out::println);

        // Pipeline 2: Estadisticas
        System.out.println("\n=== Estadisticas ===");
        var estadisticas = alumnos.stream()
            .mapToDouble(Alumno::getNotaMedia)
            .summaryStatistics();
        System.out.println("Media: " + estadisticas.getAverage());
        System.out.println("Maxima: " + estadisticas.getMax());
        System.out.println("Minima: " + estadisticas.getMin());
        System.out.println("Total: " + estadisticas.getCount());

        // Pipeline 3: Agrupar por estado
        System.out.println("\n=== Agrupados ===");
        Map<Boolean, List<Alumno>> agrupados = alumnos.stream()
            .collect(Collectors.partitioningBy(a -> a.getNotaMedia() >= 5.0));
        System.out.println("Aprobados: " + agrupados.get(true).size());
        System.out.println("Suspensos: " + agrupados.get(false).size());
    }
}

